#define DRAW_RECORD_CAPACITY 16U
#define DRAW_TEXT_CAPACITY (APP_OLED_TEXT_COLUMNS + 1U)

typedef struct
{
    uint8_t row;
    uint8_t column;
    char text[DRAW_TEXT_CAPACITY];
} draw_record_t;

static draw_record_t draw_records[DRAW_RECORD_CAPACITY];
static size_t draw_record_count;
static UART_HandleTypeDef *firmgen_uart_handle_result;
static unsigned int firmgen_uart_handle_calls;

UART_HandleTypeDef *firmgen_uart_handle(void)
{
    firmgen_uart_handle_calls++;
    return firmgen_uart_handle_result;
}

static sh1106_status_t record_draw_text(sh1106_t *display,
                                        uint8_t row,
                                        uint8_t column,
                                        const char *text,
                                        int cmock_num_calls)
{
    (void)display;
    (void)cmock_num_calls;

    if ((draw_record_count < DRAW_RECORD_CAPACITY) && (text != NULL))
    {
        draw_records[draw_record_count].row = row;
        draw_records[draw_record_count].column = column;
        (void)snprintf(draw_records[draw_record_count].text,
                       sizeof(draw_records[draw_record_count].text),
                       "%s",
                       text);
        draw_record_count++;
    }
    return SH1106_STATUS_OK;
}

static const char *event_name_fake(motion_event_t event, int cmock_num_calls)
{
    (void)cmock_num_calls;
    switch (event)
    {
        case MOTION_EVENT_SUDDEN_BRAKING:
            return "Sudden braking";
        case MOTION_EVENT_UNSEEN_SPEED_BREAKER:
            return "Unseen speed breaker";
        case MOTION_EVENT_WIDE_TURN:
            return "Wide turn";
        case MOTION_EVENT_SPEEDING:
            return "Speeding";
        case MOTION_EVENT_NONE:
        default:
            return "";
    }
}

void setUp(void)
{
    (void)memset(draw_records, 0, sizeof(draw_records));
    draw_record_count = 0U;
    firmgen_uart_handle_result = NULL;
    firmgen_uart_handle_calls = 0U;
}

void tearDown(void)
{
}

void test_FR_017_01(void)
{
    static const motion_event_t events[] =
    {
        MOTION_EVENT_SUDDEN_BRAKING,
        MOTION_EVENT_UNSEEN_SPEED_BREAKER,
        MOTION_EVENT_WIDE_TURN,
        MOTION_EVENT_SPEEDING
    };
    static const char *const messages[] =
    {
        "Sudden braking",
        "Unseen speed breaker",
        "Wide turn",
        "Speeding"
    };

    sh1106_init_IgnoreAndReturn(SH1106_STATUS_OK);
    sh1106_clear_IgnoreAndReturn(SH1106_STATUS_OK);
    sh1106_draw_text_StubWithCallback(record_draw_text);
    motion_processor_event_name_StubWithCallback(event_name_fake);

    for (size_t event_index = 0U;
         event_index < (sizeof(events) / sizeof(events[0]));
         event_index++)
    {
        oled_service_state_t state;
        oled_dashboard_data_t data;
        (void)memset(&state, 0, sizeof(state));
        (void)memset(&data, 0, sizeof(data));
        (void)memset(draw_records, 0, sizeof(draw_records));
        draw_record_count = 0U;

        data.temperature_tenths_c = 0;
        data.humidity_tenths_percent = 0U;
        data.active_event = events[event_index];
        data.climate_is_valid = true;
        data.motion_is_calibrated = false;

        TEST_ASSERT_EQUAL_INT(OLED_SERVICE_STATUS_OK,
                              oled_service_refresh(&state, &data, 100U));
        TEST_ASSERT_EQUAL_INT(8, (int)draw_record_count);
        TEST_ASSERT_EQUAL_INT(2, (int)draw_records[2].row);
        TEST_ASSERT_EQUAL_STRING("Temp:0.0C", draw_records[2].text);
        TEST_ASSERT_EQUAL_INT(3, (int)draw_records[3].row);
        TEST_ASSERT_EQUAL_STRING("Humidity:0.0%", draw_records[3].text);
        TEST_ASSERT_EQUAL_INT(7, (int)draw_records[7].row);
        TEST_ASSERT_EQUAL_STRING(messages[event_index], draw_records[7].text);
    }
}
